 * Parses the election description read from standard input into a
 * declared candidate list and a set of ballots. Throws a plain Error
 * whose message is the text that follows "error: " on failure.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidates = []
  const declared = new Set()
  let candidatesDeclared = false
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw lineError(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        throw lineError(lineNumber, 'expected candidates <name>...')
      }
      for (let j = 1; j < tokens.length; j++) {
        const name = tokens[j]
        if (!NAME_RE.test(name)) {
          throw lineError(lineNumber, `invalid candidate name ${name}`)
        }
        if (declared.has(name)) {
          throw lineError(lineNumber, `candidate ${name} is declared twice`)
        }
        declared.add(name)
        candidates.push(name)
      }
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw lineError(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw lineError(lineNumber, 'expected ballot <count> <candidate>...')
      }
      if (!/^[1-9][0-9]*$/.test(tokens[1])) {
        throw lineError(lineNumber, 'count must be a positive integer')
      }
      const count = Number(tokens[1])
      const names = []
      const seen = new Set()
      for (let j = 2; j < tokens.length; j++) {
        const name = tokens[j]
        if (!declared.has(name)) {
          throw lineError(lineNumber, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw lineError(lineNumber, `candidate ${name} is repeated`)
        }
        seen.add(name)
        names.push(name)
      }
      ballots.push({ count, names })
    } else {
      throw lineError(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (!candidatesDeclared) {
    throw new Error('no candidates')
  }

  return { candidates, ballots }
}

function lineError(lineNumber, message) {
  return new Error(`line ${lineNumber}: ${message}`)
}
"}

