function buildInstance(def) {
  return def.type === 'bucket'
    ? new TokenBucket(def.capacity, def.refill, def.per)
    : new SlidingWindow(def.limit, def.span)
}

function longestRoute(routes, key) {
  let best = null
  for (const [prefix, names] of routes) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.prefix.length)) {
      best = { prefix, names }
    }
  }
  return best ? best.names : null
}

/**
 * Replays the parsed events in order, returning one verdict per event and the
 * allowed/denied totals per key.
 */
export function simulate({ policies, routes, events }) {
  const instances = new Map()
  for (const [name, def] of policies) instances.set(name, buildInstance(def))

  const verdicts = []
  const totals = new Map()

  for (const { tick, key } of events) {
    const policyNames = longestRoute(routes, key)
    let allow = true
    let denyPolicy = null

    if (policyNames) {
      const active = policyNames.map((name) => instances.get(name))
      for (const inst of active) inst.advance(key, tick)
      for (let i = 0; i < active.length; i++) {
        if (!active[i].allows(key)) {
          allow = false
          denyPolicy = policyNames[i]
          break
        }
      }
      if (allow) for (const inst of active) inst.record(key, tick)
    }

    verdicts.push({ tick, key, allow, denyPolicy })
    const t = totals.get(key) || { allowed: 0, denied: 0 }
    if (allow) t.allowed++
    else t.denied++
    totals.set(key, t)
  }

  return { verdicts, totals }
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { parseLimiterFile } from './parser.js'
import { simulate } from './simulate.js'
import { ParseError } from './errors.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function renderReplay(verdicts) {
  let out = ''
  for (const v of verdicts) {
    out += v.allow ? `${v.tick} ${v.key} allow\n` : `${v.tick} ${v.key} deny ${v.denyPolicy}\n`
  }
  return out
}

function renderSummary(totals) {
  let out = ''
  let allowed = 0
  let denied = 0
  for (const key of [...totals.keys()].sort()) {
    const t = totals.get(key)
    out += `${key} allowed=${t.allowed} denied=${t.denied}\n`
    allowed += t.allowed
    denied += t.denied
  }
  out += `total allowed=${allowed} denied=${denied}\n`
  return out
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exitCode = 2
    return
  }

  const text = await readStdin()
  let parsed
  try {
    parsed = parseLimiterFile(text)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exitCode = 2
      return
    }
    throw err
  }

  const { verdicts, totals } = simulate(parsed)
  process.stdout.write(mode === 'replay' ? renderReplay(verdicts) : renderSummary(totals))
}

main().catch((err) => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exitCode = 2
})
"}

