/**
 * Verifies the graph is acyclic. Runs a depth-first search from every task
 * in ascending name order, walking each task's dependencies in ascending
 * name order, and throws a `CliError` (exit 3) describing the first cycle
 * such a search re-enters.
 */
export function checkAcyclic(tasks) {
  const state = new Map() // undefined = unvisited, 'active', 'done'
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const depState = state.get(dep)
      if (depState === 'active') {
        const start = stack.indexOf(dep)
        const cycle = stack.slice(start).concat(dep)
        throw new CliError(`cycle: ${cycle.join(' -> ')}`, 3)
      }
      if (depState !== 'done') visit(dep)
    }
    stack.pop()
    state.set(name, 'done')
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) !== 'done') visit(name)
  }
}

/** Computes each task's wave, where a task with no dependency is wave 0. */
export function computeDepths(tasks) {
  const depth = new Map()

  function depthOf(name) {
    if (depth.has(name)) return depth.get(name)
    let value = 0
    for (const dep of tasks.get(name).deps) value = Math.max(value, depthOf(dep) + 1)
    depth.set(name, value)
    return value
  }

  for (const name of tasks.keys()) depthOf(name)
  return depth
}

/** Computes each task's start and finish under unlimited workers. */
export function computeTimes(tasks) {
  const start = new Map()
  const finish = new Map()

  function finishOf(name) {
    if (finish.has(name)) return finish.get(name)
    let s = 0
    for (const dep of tasks.get(name).deps) s = Math.max(s, finishOf(dep))
    start.set(name, s)
    const f = s + tasks.get(name).cost
    finish.set(name, f)
    return f
  }

  for (const name of tasks.keys()) finishOf(name)
  return { start, finish }
}

/**
 * Computes each task's priority: the cost of the longest dependency chain
 * beginning at it, counting its own cost and the costs of every task
 * reachable by following dependencies down to one nothing depends on.
 */
export function computePriorities(tasks) {
  const priority = new Map()

  function priorityOf(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dep of tasks.get(name).deps) best = Math.max(best, priorityOf(dep))
    const value = tasks.get(name).cost + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) priorityOf(name)
  return priority
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-4YvhA0/src/pack.js","content":"import { computePriorities } from './graph.js'

/**
 * Simulates the graph on `workerCount` workers, greedily starting the
 * highest-priority ready task (ties broken by ascending name) on the
 * lowest-indexed free worker whenever both are available, and otherwise
 * advancing to the next instant a worker frees up.
 *
 * Returns an array of per-worker run logs: `{ name, start, finish }[]`.
 */
export function pack(tasks, workerCount) {
  const priority = computePriorities(tasks)
  const names = [...tasks.keys()]
  const remaining = new Set(names)
  const finishTime = new Map()
  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, log: [] }))

  let time = 0
  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let workerIdx = -1
      for (let i = 0; i < workerCount; i++) {
        if (workers[i].freeAt <= time) {
          workerIdx = i
          break
        }
      }
      if (workerIdx === -1) break

      let best = null
      for (const name of remaining) {
        const ready = [...tasks.get(name).deps].every((dep) => finishTime.get(dep) <= time)
        if (!ready) continue
        if (best === null) {
          best = name
        } else {
          const p = priority.get(name)
          const bestP = priority.get(best)
          if (p > bestP || (p === bestP && name < best)) best = name
        }
      }
      if (best === null) break

      const start = time
      const finish = time + tasks.get(best).cost
      workers[workerIdx].log.push({ name: best, start, finish })
      workers[workerIdx].freeAt = finish
      finishTime.set(best, finish)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break
    let next = Infinity
    for (const worker of workers) {
      if (worker.freeAt > time) next = Math.min(next, worker.freeAt)
    }
    time = next
  }

  return workers
}
"}

