      let workerIdx = -1
      for (let i = 0; i < workerCount; i++) if (workers[i].freeAt <= time) { workerIdx = i; break }
      if (workerIdx === -1) break
      let best = null
      for (const name of remaining) {
        const ready = [...tasks.get(name).deps].every(d => finishTime.get(d) <= time)
