{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-7cEhL4/src/format.js","content":"/**
 * Renders resolved merge regions (see `buildRegions`) into the output for
 * each CLI mode, and reports whether a conflict was written.
 */

/**
 * Renders `merge` and `merge2` output: resolved lines in order, with
 * conflicts marked by the usual `<<<<<<<`/`=======`/`>>>>>>>` markers.
 * `includeBase` controls whether a conflict also shows the `|||||||` base
 * section (true for `merge`, false for `merge2`).
 */
export function formatMerge(regions, includeBase) {
  const lines = []
  let conflict = false
  for (const region of regions) {
    if (region.type === 'conflict') {
      conflict = true
      lines.push('<<<<<<< mine', ...region.mine)
      if (includeBase) lines.push('||||||| base', ...region.base)
      lines.push('=======', ...region.theirs, '>>>>>>> theirs')
    } else {
      lines.push(...region.lines)
    }
  }
  return { text: lines.length === 0 ? '' : lines.join('\n') + '\n', conflict }
}

/**
 * Renders `regions` output: one summary line per region.
 */
export function formatRegions(regions) {
  const lines = []
  let conflict = false
  for (const region of regions) {
    if (region.type === 'conflict') {
      conflict = true
      lines.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else {
      lines.push(`${region.type} ${region.lines.length}`)
    }
  }
  return { text: lines.length === 0 ? '' : lines.join('\n') + '\n', conflict }
}
"}

