 * A task's priority for packing is the cost of the longest chain that
 * begins at it: its own cost, plus the priority of whichever task that
 * depends on it continues the longest chain, down to a task nothing
 * depends on.
 */
function computePriority(tasks, depsMap) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of depsMap) {
    for (const dep of deps) dependents.get(dep).push(name)
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    const forward = dependents.get(name)
    const best = forward.length === 0 ? 0 : Math.max(...forward.map(compute))
    const p = tasks.get(name) + best
    priority.set(name, p)
    return p
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulate the graph on the given number of workers with greedy priority
 * scheduling: while a worker is free and some task is ready, start the
 * ready task with the greatest priority (ties by ascending name) on the
 * free worker with the smallest index; otherwise advance time to the next
 * instant a worker frees up.
 */
export function packSchedule(tasks, depsMap, workerCount) {
  const names = [...tasks.keys()]
  const priority = computePriority(tasks, depsMap)

  const workerFreeAt = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])
  const finishTime = new Map()
  const scheduled = new Set()
  let currentTime = 0

  while (scheduled.size < names.length) {
    let progressed = true
    while (progressed) {
      progressed = false

      const freeWorkers = []
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= currentTime) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      const ready = names.filter((name) => {
        if (scheduled.has(name)) return false
        const deps = depsMap.get(name)
        if (!deps) return true
        for (const dep of deps) {
          if ((finishTime.get(dep) ?? Infinity) > currentTime) return false
        }
        return true
      })
      if (ready.length === 0) break

      ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : 1))
      const task = ready[0]
      const worker = freeWorkers[0]
      const start = currentTime
      const finish = start + tasks.get(task)

      workerLog[worker].push({ name: task, start, finish })
      workerFreeAt[worker] = finish
      finishTime.set(task, finish)
      scheduled.add(task)
      progressed = true
    }

    if (scheduled.size >= names.length) break

    const future = workerFreeAt.filter((t) => t > currentTime)
    currentTime = Math.min(...future)
  }

  const makespan = names.length === 0 ? 0 : Math.max(...finishTime.values())
  return { workerLog, makespan }
}
