/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { CliError, fail } from './errors.js'
import { parseGraph } from './parse.js'
import { checkForCycle } from './cycle.js'
import { computeSchedule } from './schedule.js'
import { packSchedule } from './pack.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) fail('workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  fail(USAGE)
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function renderWaves(names, schedule) {
  const byDepth = new Map()
  for (const name of names) {
    const d = schedule.depth.get(name)
    if (!byDepth.has(d)) byDepth.set(d, [])
    byDepth.get(d).push(name)
  }
  const maxDepth = names.length === 0 ? -1 : Math.max(...byDepth.keys())
  const lines = []
  for (let k = 0; k <= maxDepth; k++) {
    const group = (byDepth.get(k) || []).sort()
    lines.push(`wave ${k}: ${group.join(' ')}`)
  }
  lines.push(`total ${schedule.total}`)
  return lines.join('\n') + '\n'
}

function renderExplain(names, schedule) {
  const lines = names
    .slice()
    .sort()
    .map((name) => `${name} start=${schedule.start.get(name)} finish=${schedule.finish.get(name)} depth=${schedule.depth.get(name)}`)
  lines.push(`total ${schedule.total}`)
  return lines.join('\n') + '\n'
}

function renderPack(result, workerCount) {
  const lines = []
  for (let i = 0; i < workerCount; i++) {
    const tasks = result.workerLog[i]
    const rendered = tasks.map((t) => `${t.name}@${t.start}-${t.finish}`)
    lines.push(rendered.length === 0 ? `worker ${i}:` : `worker ${i}: ${rendered.join(' ')}`)
  }
  lines.push(`makespan ${result.makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = await readStdin()
  const { tasks, depsMap } = parseGraph(input)
  const names = [...tasks.keys()].sort()

  checkForCycle(names, depsMap)

  if (mode === 'waves') {
    const schedule = computeSchedule(tasks, depsMap)
    process.stdout.write(renderWaves(names, schedule))
  } else if (mode === 'explain') {
    const schedule = computeSchedule(tasks, depsMap)
    process.stdout.write(renderExplain(names, schedule))
  } else {
    const result = packSchedule(tasks, depsMap, workers)
    process.stdout.write(renderPack(result, workers))
  }
}

main().then(
  () => {},
  (err) => {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`, () => {
        process.exitCode = err.code
      })
    } else {
      process.stderr.write(`error: ${err.message}\n`, () => {
        process.exitCode = 2
      })
    }
  },
)
"}

