 * A hand-written scanner for the tiny language described in the task. It
 * turns UTF-8 source text into a flat list of tokens, or throws a ScanError
 * carrying the line, column and reason of the first problem it hits.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

// Longest match wins, so multi-character operators must precede any
// single-character operator that is one of their prefixes.
const PUNCTS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const isDec = (ch) => typeof ch === 'string' && ch >= '0' && ch <= '9'
const isHex = (ch) => typeof ch === 'string' && /^[0-9a-fA-F]$/.test(ch)
const isBin = (ch) => ch === '0' || ch === '1'
const isOct = (ch) => typeof ch === 'string' && ch >= '0' && ch <= '7'
const isLetterOrUnderscore = (ch) => typeof ch === 'string' && /^[A-Za-z_]$/.test(ch)
const isWordChar = (ch) => typeof ch === 'string' && /^[A-Za-z0-9_]$/.test(ch)

export function scan(src) {
  const cps = Array.from(src)
  const n = cps.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  function peek(offset = 0) {
    return cps[i + offset]
  }

  function advance() {
    const ch = cps[i]
    i++
    if (ch === '\n') {
      line++
      col = 1
    } else if (ch === '\t') {
      col = (Math.floor((col - 1) / 4) + 1) * 4 + 1
    } else {
      col++
    }
    return ch
  }

  function fail(atLine, atCol, reason) {
    throw new ScanError(atLine, atCol, reason)
  }

  function consumeDigitRun(isDigit) {
    let text = ''
    while (i < n) {
      const ch = peek()
      if (isDigit(ch)) {
        text += ch
        advance()
        continue
      }
      if (ch === '_' && text.length > 0 && isDigit(text[text.length - 1]) && isDigit(peek(1))) {
        text += ch
        advance()
        continue
      }
      break
    }
    return text
  }

  function scanNumber() {
    const startLine = line
    const startCol = col
    let text = ''
    let prefixed = false

    if (peek() === '0' && (peek(1) === 'x' || peek(1) === 'X' || peek(1) === 'b' || peek(1) === 'B' || peek(1) === 'o' || peek(1) === 'O')) {
      prefixed = true
      text += advance()
      const marker = peek()
      text += advance()
      const isDigit = marker === 'x' || marker === 'X' ? isHex : marker === 'b' || marker === 'B' ? isBin : isOct
      text += consumeDigitRun(isDigit)
    } else {
      text += consumeDigitRun(isDec)
      if (peek() === '.' && isDec(peek(1))) {
        text += advance()
        text += consumeDigitRun(isDec)
      }
      if (peek() === 'e' || peek() === 'E') {
        const hasSign = peek(1) === '+' || peek(1) === '-'
        const digitAfter = hasSign ? peek(2) : peek(1)
        if (isDec(digitAfter)) {
          text += advance()
          if (hasSign) text += advance()
          text += consumeDigitRun(isDec)
        }
      }
    }

    const noDigitsAfterPrefix = prefixed && !/[0-9a-fA-F]/.test(text.slice(2))
    const hasTrailingGarbage = isWordChar(peek())

    if (noDigitsAfterPrefix || hasTrailingGarbage) {
      while (i < n && isWordChar(peek())) text += advance()
      fail(startLine, startCol, `invalid number ${text}`)
    }

    tokens.push({ line: startLine, col: startCol, kind: 'number', body: text })
  }

  function scanIdentifier() {
    const startLine = line
    const startCol = col
    let text = ''
    while (i < n && isWordChar(peek())) text += advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    tokens.push({ line: startLine, col: startCol, kind, body: text })
  }

  function decodeStringEscape(sLine, sCol) {
    const bsLine = line
    const bsCol = col
    advance() // consume backslash
    if (i >= n) fail(sLine, sCol, 'unterminated string')
    const esc = peek()
    switch (esc) {
      case 'n':
        advance()
        return '\n'
      case 't':
        advance()
        return '\t'
      case 'r':
        advance()
        return '\r'
      case '\\':
        advance()
        return '\\'
      case '"':
        advance()
        return '"'
      case '0':
        advance()
        return '\0'
      case 'x': {
        advance()
        let hex = ''
        for (let k = 0; k < 2; k++) {
          if (i >= n) fail(sLine, sCol, 'unterminated string')
          if (!isHex(peek())) fail(bsLine, bsCol, 'invalid escape \\x')
          hex += advance()
        }
        return String.fromCharCode(parseInt(hex, 16))
      }
      case 'u': {
        advance()
        if (peek() !== '{') fail(bsLine, bsCol, 'invalid escape \\u')
        advance()
        let hex = ''
        while (true) {
          if (i >= n) fail(sLine, sCol, 'unterminated string')
          if (peek() === '}') break
          if (!isHex(peek())) fail(bsLine, bsCol, 'invalid escape \\u')
          hex += advance()
        }
        if (hex.length === 0) fail(bsLine, bsCol, 'invalid escape \\u')
        advance() // consume '}'
        const codepoint = parseInt(hex, 16)
        if (codepoint > 0x10ffff) fail(bsLine, bsCol, 'invalid escape \\u')
        return String.fromCodePoint(codepoint)
      }
      default:
        fail(bsLine, bsCol, `invalid escape \\${esc}`)
    }
  }

  function scanString() {
    const startLine = line
    const startCol = col
    advance() // opening quote
    let value = ''
    while (true) {
      if (i >= n) fail(startLine, startCol, 'unterminated string')
      const ch = peek()
      if (ch === '"') {
        advance()
        break
      }
      if (ch === '\n') fail(line, col, 'newline in string')
      if (ch === '\\') {
        value += decodeStringEscape(startLine, startCol)
      } else {
        value += advance()
      }
    }
    tokens.push({ line: startLine, col: startCol, kind: 'string', body: JSON.stringify(value) })
  }

  function scanRawString() {
    const startLine = line
    const startCol = col
    advance() // 'r'
    advance() // opening quote
    let value = ''
    while (true) {
      if (i >= n) fail(startLine, startCol, 'unterminated string')
      const ch = peek()
      if (ch === '"') {
        advance()
        break
      }
      value += advance()
    }
    tokens.push({ line: startLine, col: startCol, kind: 'rawstring', body: JSON.stringify(value) })
  }

  while (i < n) {
    const ch = peek()

    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      advance()
      continue
    }

    if (ch === '/' && peek(1) === '/') {
      advance()
      advance()
      while (i < n && peek() !== '\n') advance()
      continue
    }

    if (ch === '/' && peek(1) === '*') {
      const openLine = line
      const openCol = col
      advance()
      advance()
      let depth = 1
      while (depth > 0) {
        if (i >= n) fail(openLine, openCol, 'unterminated block comment')
        if (peek() === '/' && peek(1) === '*') {
          advance()
          advance()
          depth++
          continue
        }
        if (peek() === '*' && peek(1) === '/') {
          advance()
          advance()
          depth--
          continue
        }
        advance()
      }
      continue
    }

    if (ch === 'r' && peek(1) === '"') {
      scanRawString()
      continue
    }

    if (ch === '"') {
      scanString()
      continue
    }

    if (isLetterOrUnderscore(ch)) {
      scanIdentifier()
      continue
    }

    if (isDec(ch)) {
      scanNumber()
      continue
    }

    let matched = null
    for (const p of PUNCTS) {
      let ok = true
      for (let k = 0; k < p.length; k++) {
        if (peek(k) !== p[k]) {
          ok = false
          break
        }
      }
      if (ok) {
        matched = p
        break
      }
    }
    if (matched) {
      const startLine = line
      const startCol = col
      for (let k = 0; k < matched.length; k++) advance()
      tokens.push({ line: startLine, col: startCol, kind: 'punct', body: matched })
      continue
    }

    fail(line, col, `unexpected character ${ch}`)
  }

  return tokens
}
"}

