export function parse(str) {
  let rest = str
  let scheme = null
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  let hasAuthority = false
  let userinfo = null
  let host = null
  let port = null
  if (rest.startsWith('//')) {
    hasAuthority = true
    let authEnd = rest.length
    for (let j = 2; j < rest.length; j++) {
      const c = rest[j]
      if (c === '/' || c === '?' || c === '#') {
        authEnd = j
        break
      }
    }
    const authority = rest.slice(2, authEnd)
    rest = rest.slice(authEnd)

    let authRest = authority
    const atIdx = authority.lastIndexOf('@')
    if (atIdx !== -1) {
      userinfo = authority.slice(0, atIdx)
      authRest = authority.slice(atIdx + 1)
    }
    const bracketIdx = authRest.lastIndexOf(']')
    const searchStart = bracketIdx === -1 ? 0 : bracketIdx
    const colonIdx = authRest.indexOf(':', searchStart)
    if (colonIdx !== -1) {
      host = authRest.slice(0, colonIdx)
      port = authRest.slice(colonIdx + 1)
    } else {
      host = authRest
    }
  }

  const hashIdx = rest.indexOf('#')
  const beforeHash = hashIdx === -1 ? rest : rest.slice(0, hashIdx)
  const fragment = hashIdx === -1 ? null : rest.slice(hashIdx + 1)
  const qIdx = beforeHash.indexOf('?')
  const path = qIdx === -1 ? beforeHash : beforeHash.slice(0, qIdx)
  const query = qIdx === -1 ? null : beforeHash.slice(qIdx + 1)

  return { scheme, hasAuthority, userinfo, host, port, path, query, fragment }
}

/**
 * @param {ReturnType<typeof parse>} c
 * @returns {string}
 */
export function serialize(c) {
  let out = ''
  if (c.scheme !== null) out += c.scheme + ':'
  if (c.hasAuthority) {
    out += '//'
    if (c.userinfo !== null) out += c.userinfo + '@'
    out += c.host
    if (c.port !== null) out += ':' + c.port
  }
  out += c.path
  if (c.query !== null) out += '?' + c.query
  if (c.fragment !== null) out += '#' + c.fragment
  return out
