const DEFAULT_PORTS = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }

/**
 * Normalizes a parsed URI reference. Percent-encoding truncation is checked
 * component by component in the order path, userinfo, host, query,
 * fragment, so the first bad one names the error.
 * @param {import('./parse.js').parse extends (...a: any) => infer R ? R : never} c
 * @returns {typeof c}
 */
export function normalizeComponents(c) {
  const scheme = asciiLower(c.scheme)

  const path = normalizePercent(c.path, 'path')
  const userinfo = normalizePercent(c.userinfo, 'userinfo')
  const host = normalizePercent(c.host, 'host')
  const query = normalizePercent(c.query, 'query')
  const fragment = normalizePercent(c.fragment, 'fragment')

  const lowerHost = asciiLower(host)

  let port = c.port
  if (c.hasAuthority) {
    if (port === '') {
      port = null
    } else if (port !== null && scheme !== null && port === DEFAULT_PORTS[scheme]) {
      port = null
    }
  }

  let newPath = removeDotSegments(path)
  if (c.hasAuthority && newPath === '') newPath = '/'

  return {
    scheme,
    hasAuthority: c.hasAuthority,
    userinfo,
    host: lowerHost,
    port,
    path: newPath,
    query,
    fragment,
  }
}
