{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-BrQJZj/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { splitDocuments } from './document.js'
import { mergeDocuments } from './merge.js'
import { renderMerge, renderMerge2, renderRegions } from './output.js'

const MODES = {
  merge: renderMerge,
  merge2: renderMerge2,
  regions: renderRegions,
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`, () => process.exit(2))
}

async function main() {
  const [mode] = process.argv.slice(2)
  const render = MODES[mode]
  if (!render) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const input = await readStdin()
  let documents
  try {
    documents = splitDocuments(input)
  } catch (error) {
    fail(error.message)
    return
  }

  const segments = mergeDocuments(documents.mine, documents.base, documents.theirs)
  const { lines, hadConflict } = render(segments)
  const text = lines.length > 0 ? `${lines.join('\n')}\n` : ''
  process.stdout.write(text, () => process.exit(hadConflict ? 1 : 0))
}

main()
"}

