{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-CxmbJ2/src/diff.js","content":"/**
 * Longest-common-subsequence diff between a base document and one side,
 * comparing whole lines as exact strings.
 */

/**
 * Computes the changes that turn `base` into `side`, backed by an LCS over
 * whole lines with a specific tie-break: on equally long candidate
 * subsequences, the one whose matches come earliest wins. Reconstructing the
 * alignment from the start, a match is taken whenever the two current lines
 * are equal; otherwise the side whose remaining subsequence is at least as
 * long as the other's is advanced, with the base preferred on a tie.
 *
 * Each returned change describes a run of `base` lines (`baseStart` to
 * `baseEnd`, half-open) replaced by a run of `side`'s `lines`. An insertion
 * has `baseStart === baseEnd`; a deletion has an empty `lines` array.
 * Changes are returned in base order.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length
  const width = m + 1
  const dp = new Uint32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      const here = i * width + j
      dp[here] = base[i] === side[j] ? dp[here + width + 1] + 1 : Math.max(dp[here + width], dp[here + 1])
    }
  }

  const changes = []
  let changeStart = null
  const flush = (baseEnd, sideEnd) => {
    if (changeStart !== null) {
      changes.push({ baseStart: changeStart.i, baseEnd, lines: side.slice(changeStart.j, sideEnd) })
      changeStart = null
    }
  }

  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(i, j)
      i++
      j++
    } else {
      if (changeStart === null) changeStart = { i, j }
      if (dp[(i + 1) * width + j] >= dp[i * width + j + 1]) i++
      else j++
    }
  }
  if (changeStart === null && (i < n || j < m)) changeStart = { i, j }
  flush(n, m)

  return changes
}
"}

