 * Renders merge segments as the `merge`, `merge2` and `regions` output
 * formats.
 */

/**
 * Formats segments as merged text, writing a conflict marker block for each
 * conflict. When `includeBase` is false the `||||||| base` section is left
 * out, matching `merge2`.
 */
export function formatMerge(segments, { includeBase }) {
  const out = []
  for (const segment of segments) {
    if (segment.kind === 'conflict') {
      out.push('<<<<<<< mine', ...segment.mine)
      if (includeBase) out.push('||||||| base', ...segment.base)
      out.push('=======', ...segment.theirs, '>>>>>>> theirs')
    } else {
      out.push(...segment.lines)
    }
  }
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}

/**
 * Formats segments as the `regions` report: one line per segment naming its
 * kind and the line count it resolves to, or the three counts of a conflict.
 */
export function formatRegions(segments) {
  const out = segments.map(segment =>
    segment.kind === 'conflict'
      ? `conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}`
      : `${segment.kind} ${segment.lines.length}`,
  )
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
"}

