 * Character-level scanning primitives: the codepoint cursor that tracks line
 * and column, the tab/newline column rules, and the lexical error type.
 */

export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

export class Cursor {
  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  advance() {
    const c = this.chars[this.pos]
    this.pos++
    if (c === '\n') {
