  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

function skipTrivia(cursor) {
  for (;;) {
    const c = cursor.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      cursor.advance()
      continue
    }
    if (c === '/' && cursor.peek(1) === '/') {
      while (!cursor.atEnd() && cursor.peek() !== '\n') cursor.advance()
      continue
    }
    if (c === '/' && cursor.peek(1) === '*') {
      const startLine = cursor.line
      const startCol = cursor.col
      cursor.advance()
      cursor.advance()
      let depth = 1
      while (depth > 0) {
        if (cursor.atEnd()) throw new LexError(startLine, startCol, 'unterminated block comment')
        const ch = cursor.advance()
        if (ch === '/' && cursor.peek() === '*') {
          cursor.advance()
          depth++
        } else if (ch === '*' && cursor.peek() === '/') {
          cursor.advance()
          depth--
        }
      }
      continue
    }
    break
