  const startLine = cursor.line
  const startCol = cursor.col
  let text = ''
  while (!cursor.atEnd() && isIdentContinue(cursor.peek())) {
    text += cursor.advance()
  }
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, text, line: startLine, col: startCol }
