 * A cursor over the source text that tracks line and column as code points
 * are consumed. A tab advances the column to the next multiple of 4 plus 1;
 * a line feed resets the column to 1 and advances the line; every other
 * code point advances the column by 1.
 */
export class Reader {
  constructor(src) {
    this.src = src
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.i >= this.src.length
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  /** A single UTF-16 unit at an offset from the cursor, or '' past the end. */
  peekChar(offset = 0) {
    const idx = this.i + offset
    if (idx >= this.src.length) return ''
    return this.src[idx]
  }

  /** The full code point at the cursor (a surrogate pair counts as one), or ''. */
  peekCodePoint() {
    if (this.eof()) return ''
    return String.fromCodePoint(this.src.codePointAt(this.i))
  }

  /** Consume one code point and update line/column, returning it as a string. */
  advance() {
    if (this.eof()) return ''
    const cp = this.src.codePointAt(this.i)
    const ch = String.fromCodePoint(cp)
    this.i += ch.length
    if (cp === 10) {
      this.line += 1
      this.col = 1
    } else if (cp === 9) {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col += 1
    }
    return ch
  }
}
