/** Read digit(_?digit)*, where the digits satisfy isDigit; '' if none. */
function readDigitRun(reader, isDigit) {
  let text = ''
  if (!isDigit(reader.peekChar())) return text
  text += reader.advance()
  while (true) {
    if (isDigit(reader.peekChar())) {
      text += reader.advance()
      continue
    }
    if (reader.peekChar() === '_' && isDigit(reader.peekChar(1))) {
      text += reader.advance()
      continue
    }
    break
  }
  return text
}

