 * Scan a number starting at the cursor (which sits on a decimal digit).
 * Throws ScanError('invalid number <text>') when the prefix has no digit
 * after it, or when the number is followed immediately by a letter, digit
 * or underscore the grammar did not consume; the reported text includes
 * every such trailing character.
 */
export function scanNumber(reader) {
  const start = reader.pos()
  let text = ''
  let valid = true

  const prefix = reader.peekChar(1).toLowerCase()
  if (reader.peekChar() === '0' && prefix === 'x') {
    text += reader.advance() + reader.advance()
    const run = readDigitRun(reader, isHexDigit)
    text += run
    if (run.length === 0) valid = false
  } else if (reader.peekChar() === '0' && prefix === 'b') {
    text += reader.advance() + reader.advance()
    const run = readDigitRun(reader, isBinDigit)
    text += run
    if (run.length === 0) valid = false
  } else if (reader.peekChar() === '0' && prefix === 'o') {
    text += reader.advance() + reader.advance()
    const run = readDigitRun(reader, isOctDigit)
    text += run
    if (run.length === 0) valid = false
  } else {
    text += readDigitRun(reader, isDecDigit)

    if (reader.peekChar() === '.' && isDecDigit(reader.peekChar(1))) {
      text += reader.advance()
      text += readDigitRun(reader, isDecDigit)
    }

    const c0 = reader.peekChar()
    if (c0 === 'e' || c0 === 'E') {
      const hasSign = reader.peekChar(1) === '+' || reader.peekChar(1) === '-'
      const digitOffset = hasSign ? 2 : 1
      if (isDecDigit(reader.peekChar(digitOffset))) {
        text += reader.advance()
        if (hasSign) text += reader.advance()
        text += readDigitRun(reader, isDecDigit)
      }
    }
  }

  if (!valid || isIdentContinue(reader.peekChar())) {
    while (isIdentContinue(reader.peekChar())) text += reader.advance()
