  const esc = reader.peekChar()
  switch (esc) {
    case 'n':
      reader.advance()
      return value + '\n'
    case 't':
      reader.advance()
      return value + '\t'
    case 'r':
      reader.advance()
      return value + '\r'
    case '\\':
      reader.advance()
      return value + '\\'
    case '"':
      reader.advance()
      return value + '"'
    case '0':
      reader.advance()
      return value + '\0'
