/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import fs from 'node:fs'
import { scan } from './scan.js'
import { ScanError } from './errors.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function bodyOf(token) {
  if (token.kind === 'string' || token.kind === 'rawstring') return JSON.stringify(token.value)
  return token.text
}

function renderTokens(tokens) {
  let out = ''
  for (const token of tokens) {
    out += `${token.pos.line}:${token.pos.col} ${token.kind} ${bodyOf(token)}\n`
  }
  return out
}

function renderStats(stats) {
  let out = ''
  let total = 0
  for (const kind of KIND_ORDER) {
    out += `${kind} ${stats[kind]}\n`
    total += stats[kind]
  }
  out += `total ${total}\n`
  return out
}

function fail(message, code) {
  process.stderr.write(`${message}\n`)
  process.exitCode = code
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    fail('error: usage: cli.js tokens|stats', 2)
    return
  }
  const mode = args[0]
  const src = readStdin()

  let result
  try {
    result = scan(src)
  } catch (err) {
    if (err instanceof ScanError) {
      fail(`error: ${err.pos.line}:${err.pos.col}: ${err.reason}`, 2)
      return
    }
    throw err
  }

  const out = mode === 'tokens' ? renderTokens(result.tokens) : renderStats(result.stats)
  process.stdout.write(out)
}

main()
"}

