 * Parsing of the election input format into a candidate list and a ballot
 * list, or a `ParseError` describing the first line that fails to conform.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(line === undefined ? `error: ${message}` : `error: line ${line}: ${message}`)
    this.line = line
  }
}

/**
 * Parses the raw election text into `{ candidates, ballots }`, where
 * `candidates` is the declared candidate names in declaration order and
 * `ballots` is a list of `{ count, prefs }`.
 */
export function parseElection(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNum = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNum)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError('expected candidates <name>...', lineNum)
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNum)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNum)
        }
        candidateSet.add(name)
      }
      candidates = names
      continue
    }

    if (directive === 'ballot') {
      if (candidates === null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNum)
      }
      const rest = tokens.slice(1)
      if (rest.length < 2) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNum)
      }
      const [countToken, ...names] = rest
      if (!COUNT_RE.test(countToken)) {
        throw new ParseError('count must be a positive integer', lineNum)
      }
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNum)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNum)
        }
        seen.add(name)
      }
      ballots.push({ count: Number(countToken), prefs: names })
      continue
    }

    throw new ParseError(`unknown directive ${directive}`, lineNum)
  }

  if (candidates === null) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

