  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable(true)
  let currentTable = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i]
    if (BLANK_OR_COMMENT.test(raw)) continue
    const lineNo = i + 1
    const cursor = new LineCursor(raw, lineNo)
    cursor.skipWsTabs()

    if (cursor.peek() === '[') {
