 * Splits raw standard input into the three documents (mine, base, theirs)
 * that a `%%%` line separates.
 */

/**
 * @param {string} raw The full text read from standard input.
 * @returns {string[][]|null} The three documents, or null when the input
 *   does not hold exactly three parts.
 */
export function parseInput(raw) {
  const lines = raw.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }

  if (docs.length !== 3) return null
  return docs
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-ZN4Zvf/src/lcsMatch.js","content":"/**
 * Computes the longest common subsequence between the base document and one
 * side, using the earliest-match tie-break the specification describes.
 */

/**
 * @param {string[]} base
 * @param {string[]} side
 * @returns {Array<[number, number]>} Matched index pairs, `[baseIndex,
 *   sideIndex]`, in increasing order of both indices.
 */
export function computeMatches(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] holds the LCS length of base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Uint32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) dp[i][j] = dp[i + 1][j + 1] + 1
      else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}
"}

