{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-aA7psh/src/parse.js","content":"/**
 * Parses an election description into a declared candidate list and a set of
 * ballots. Throws an `Error` whose `message` is the text that follows
 * `error: ` in the specification's diagnostics.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidates = []
  const candidateSet = new Set()
  let candidatesDeclared = false
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw fail(lineNumber, 'expected candidates <name>...')
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw fail(lineNumber, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          throw fail(lineNumber, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw fail(lineNumber, 'expected ballot <count> <candidate>...')
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        throw fail(lineNumber, 'count must be a positive integer')
      }
      const count = Number(countToken)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw fail(lineNumber, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw fail(lineNumber, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, candidates: names })
    } else {
      throw fail(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (!candidatesDeclared) {
    const err = new Error('no candidates')
    err.noLineNumber = true
    throw err
  }

  return { candidates, ballots }
}

function fail(lineNumber, message) {
  return new Error(`line ${lineNumber}: ${message}`)
}
"}

