{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-aA7psh/src/format.js","content":"/**
 * Renders the round-by-round or summary text the CLI prints on success.
 */

export function formatRounds(rounds, winner) {
  const lines = []
  rounds.forEach((round, i) => {
    lines.push(`round ${i + 1}: ${formatCounts(round.tally)} exhausted=${round.exhausted}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(winner === null ? 'no winner' : `winner ${winner}`)
  return lines.join('\n') + '\n'
}

export function formatTally(rounds, winner) {
  const lines = [`rounds ${rounds.length}`, winner === null ? 'no winner' : `winner ${winner}`]
  return lines.join('\n') + '\n'
}

function formatCounts(tally) {
  const entries = [...tally.entries()]
  entries.sort(([nameA, votesA], [nameB, votesB]) => {
    if (votesA !== votesB) return votesB - votesA
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  return entries.map(([name, votes]) => `${name}=${votes}`).join(' ')
}
"}

