{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-be2WvB/src/simulate.js","content":"/**
 * Replays a parsed program's events against its policies and routes,
 * producing one verdict per event in log order.
 */
import { Bucket, Window } from './policies.js'

function makePolicy(decl) {
  return decl.type === 'bucket' ? new Bucket(decl.capacity, decl.refill, decl.per) : new Window(decl.limit, decl.span)
}

function routeFor(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

export function simulate(program) {
  const instances = new Map()
  for (const [name, decl] of program.policies) instances.set(name, makePolicy(decl))

  const verdicts = []
  for (const { tick, key } of program.events) {
    const route = routeFor(program.routes, key)
    if (!route) {
      verdicts.push({ tick, key, allow: true, deniedBy: null })
      continue
    }

    const policyList = route.policyNames.map((name) => instances.get(name))
    for (const policy of policyList) policy.advance(key, tick)

    let deniedBy = null
    for (let i = 0; i < policyList.length; i++) {
      if (!policyList[i].allows(key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of policyList) policy.record(key, tick)
    }
    verdicts.push({ tick, key, allow: deniedBy === null, deniedBy })
  }
  return verdicts
}
"}

