{"file_path":"src/parse.js","content":"/**
 * Splits a URI reference string into its generic-syntax components, per
 * RFC 3986. Absent components are `null`; the path is always a string,
 * possibly empty. No validation (such as percent-encoding checks) happens
 * here; that is left to normalize.js.
 */

function firstIndexOfAny(s, chars) {
  let best = -1
  for (const c of chars) {
    const idx = s.indexOf(c)
    if (idx !== -1 && (best === -1 || idx < best)) best = idx
  }
  return best
}

function splitAuthority(authorityText) {
  let userinfo = null
  let rest = authorityText
  const atIdx = authorityText.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authorityText.slice(0, atIdx)
    rest = authorityText.slice(atIdx + 1)
  }
  const bracketIdx = rest.lastIndexOf(']')
  const colonIdx = rest.indexOf(':', bracketIdx + 1)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
    port = null
  }
  return { userinfo, host, port }
}

export function parseReference(text) {
  let rest = text
  let scheme = null
  const specialIdx = firstIndexOfAny(rest, [':', '/', '?', '#'])
  if (specialIdx !== -1 && rest[specialIdx] === ':') {
    scheme = rest.slice(0, specialIdx)
    rest = rest.slice(specialIdx + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const endIdx = firstIndexOfAny(rest, ['/', '?', '#'])
    const authorityText = endIdx === -1 ? rest : rest.slice(0, endIdx)
    rest = endIdx === -1 ? '' : rest.slice(endIdx)
    authority = splitAuthority(authorityText)
  }

  const qIdx = firstIndexOfAny(rest, ['?', '#'])
  let path, remainder
  if (qIdx === -1) {
    path = rest
    remainder = ''
  } else {
    path = rest.slice(0, qIdx)
    remainder = rest.slice(qIdx)
  }

  let query = null
  let fragment = null
  if (remainder.startsWith('?')) {
    const hIdx = remainder.indexOf('#')
    if (hIdx === -1) {
      query = remainder.slice(1)
    } else {
      query = remainder.slice(1, hIdx)
      fragment = remainder.slice(hIdx + 1)
    }
  } else if (remainder.startsWith('#')) {
    fragment = remainder.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

export function serializeReference(ref) {
  let out = ''
  if (ref.scheme !== null) out += ref.scheme + ':'
  if (ref.authority !== null) {
    out += '//'
    if (ref.authority.userinfo !== null) out += ref.authority.userinfo + '@'
    out += ref.authority.host
    if (ref.authority.port !== null) out += ':' + ref.authority.port
  }
  out += ref.path
  if (ref.query !== null) out += '?' + ref.query
  if (ref.fragment !== null) out += '#' + ref.fragment
  return out
}
"}

