{"file_path":"src/resolve.js","content":"/**
 * Resolves a reference against a base URI per RFC 3986 section 5.2.2,
 * strict form (a reference that repeats the base's scheme is still
 * treated as an absolute URI). The result is not yet normalized; call
 * normalizeReference on it.
 */

import { removeDotSegments } from './dot-segments.js'

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

export function resolveReference(base, ref) {
  if (ref.scheme !== null) {
    return {
      scheme: ref.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
      fragment: ref.fragment,
    }
  }

  if (ref.authority !== null) {
    return {
      scheme: base.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
      fragment: ref.fragment,
    }
  }

  if (ref.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== null ? ref.query : base.query,
      fragment: ref.fragment,
    }
  }

  const path = ref.path.startsWith('/')
    ? removeDotSegments(ref.path)
    : removeDotSegments(mergePaths(base, ref.path))

  return {
    scheme: base.scheme,
    authority: base.authority,
    path,
    query: ref.query,
    fragment: ref.fragment,
  }
}
"}

