/** Parses a configuration document, returning its root table. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable([])
  let current = root

  for (let li = 0; li < lines.length; li++) {
    const lineNo = li + 1
    const raw = lines[li]

    let j = 0
    while (j < raw.length && (raw[j] === ' ' || raw[j] === '\t')) j++
    if (j >= raw.length) continue
    if (raw[j] === '#' || raw[j] === ';') continue

    const cur = new Cursor(raw, lineNo)
    cur.i = j

    if (cur.peek() === '[') {
      cur.next()
      if (cur.peek() === '[') {
        cur.next()
        const segments = parseDottedName(cur)
        cur.skipWs()
        expectChar(cur, ']', 'unterminated table header')
        cur.skipWs()
