        cur.skipWs()
        expectChar(cur, ']', 'unterminated table header')
        checkTrailing(cur, 'trailing text after a table header')
        current = resolveTableHeader(root, segments, lineNo)
      }
      continue
    }

    const segments = parseDottedName(cur)
    cur.skipWs()
    if (cur.peek() !== '=') throw cur.err('expected key = value')
    cur.next()
    const value = parseValue(cur)
    checkTrailing(cur, 'trailing text after a value')
    assignDotted(current, segments, value, lineNo)
  }

  return root
}
