 * Parsing of the election input format into a structure the counting
 * module can consume: an ordered list of candidate names and an ordered
 * list of ballots, each a count paired with a ranked list of names.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** Thrown for any input that fails to parse; carries the exact message. */
export class ParseError extends Error {}

/**
 * Parses the raw election text and returns { candidates, ballots }.
 * `candidates` is an array of names in declaration order. `ballots` is
 * an array of { count, names } in the order they were read.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidates = []
  const candidateSet = new Set()
  const ballots = []
  let candidatesDeclared = false

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidatesDeclared) {
        throw new ParseError(`error: line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 2) {
        throw new ParseError(`error: line ${lineNumber}: expected candidates <name>...`)
      }
      for (let j = 1; j < tokens.length; j++) {
        const name = tokens[j]
        if (!NAME_RE.test(name)) {
          throw new ParseError(`error: line ${lineNumber}: invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`error: line ${lineNumber}: candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      candidatesDeclared = true
      continue
    }

    if (word === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError(`error: line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 3) {
        throw new ParseError(`error: line ${lineNumber}: expected ballot <count> <candidate>...`)
      }
      if (!COUNT_RE.test(tokens[1])) {
        throw new ParseError(`error: line ${lineNumber}: count must be a positive integer`)
      }
      const count = Number(tokens[1])
      const names = []
      const seen = new Set()
      for (let j = 2; j < tokens.length; j++) {
        const name = tokens[j]
        if (!candidateSet.has(name)) {
          throw new ParseError(`error: line ${lineNumber}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(`error: line ${lineNumber}: candidate ${name} is repeated`)
        }
        seen.add(name)
        names.push(name)
      }
      ballots.push({ count, names })
      continue
    }

    throw new ParseError(`error: line ${lineNumber}: unknown directive ${word}`)
  }

  if (!candidatesDeclared) {
    throw new ParseError('error: no candidates')
  }

  return { candidates, ballots }
}
"}

