{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-cFejxh/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './election.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('error: usage: cli.js rounds|tally')
  }

  const input = require_stdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) fail(err.message)
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      lines.push(formatRound(index + 1, round))
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }
  lines.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(lines.join('\n') + '\n')
}

function formatRound(number, round) {
  const entries = [...round.votes.entries()].sort((a, b) => {
    if (a[1] !== b[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${number}: ${parts.join(' ')}`
}

function require_stdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

main()
"}

