  const mode = args.length === 1 ? args[0] : null
  if (mode !== 'normalize' && mode !== 'resolve') {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = await readAllStdin()
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        results.push(normalize(line))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError('expected a base and a reference')
        }
        const base = line.slice(0, spaceIdx)
        const ref = line.slice(spaceIdx + 1)
        results.push(resolve(base, ref))
      }
    } catch (e) {
      if (e instanceof UriError) {
        process.stderr.write(`error: line ${lineNo}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }

  process.stdout.write(results.map((r) => r + '\n').join(''))
  process.exit(0)
