 * Structural extraction of the cells a parsed formula names directly,
 * independent of how it evaluates: both branches of an IF and a range
 * written from either corner all contribute their cells.
 */
import { parseAddress, expandRange, compareAddressKeys } from './address.js'
import { parseFormula } from './formulaParser.js'

function collect(node, set) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'addr': {
      const info = parseAddress(node.word)
      if (info) set.add(info.key)
      return
    }
    case 'unary':
      collect(node.operand, set)
      return
    case 'bin':
      collect(node.left, set)
      collect(node.right, set)
      return
    case 'call':
      for (const arg of node.args) {
        if (arg.type === 'range') {
          const keys = expandRange(arg.a, arg.b)
          if (keys) for (const k of keys) set.add(k)
        } else {
          collect(arg, set)
        }
      }
      return
    default:
      throw new Error('unreachable')
  }
}

