 * Parses a sheet from standard input text into a Map of normalized
 * address key -> raw content string, in declaration order.
 */
import { parseAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/** Throws SheetError on the first invalid address or duplicate declaration. */
export function parseSheet(input) {
  const cells = new Map()
  const lines = splitLines(input)
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue
    const spaceIdx = stripped.search(/[ \t]/)
    let addressText, content
    if (spaceIdx === -1) {
      addressText = stripped
      content = ''
    } else {
      addressText = stripped.slice(0, spaceIdx)
      let rest = stripped.slice(spaceIdx)
      const run = rest.match(/^[ \t]+/)
      content = rest.slice(run[0].length)
    }
    const upper = addressText.toUpperCase()
    const info = parseAddress(upper)
    if (!info) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${upper}`)
    }
    if (cells.has(info.key)) {
      throw new SheetError(`line ${lineNo}: cell ${upper} is declared twice`)
    }
    cells.set(info.key, content)
  }
  return cells
}
"}

