{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-o7cCD4/src/schedule.js","content":"import { computePriorities } from './graph.js'

/**
 * Simulates the build graph on the given number of workers, as described in
 * the `pack` mode of the CLI. Assumes the graph is acyclic. Returns
 * `{ workerRuns, makespan }`, where `workerRuns[i]` is the array of
 * `{ name, start, finish }` the i-th worker ran, in the order it ran them.
 */
export function packSchedule(tasks, depMap, workerCount) {
  const names = [...tasks.keys()]
  const workerRuns = Array.from({ length: workerCount }, () => [])

  if (names.length === 0) return { workerRuns, makespan: 0 }

  const priority = computePriorities(tasks, depMap)

  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const [name, deps] of depMap) {
    for (const d of deps) dependents.get(d).push(name)
  }

  const remaining = new Map()
  for (const name of names) remaining.set(name, depMap.get(name).size)

  const readySet = new Set(names.filter((n) => remaining.get(n) === 0))
  const pendingFinishes = [] // { name, finish }, for cost > 0 tasks not yet applied

  const workerFreeAt = new Array(workerCount).fill(0)
  let doneCount = 0
  let currentTime = 0

  function applyFinish(name) {
    for (const dep of dependents.get(name)) {
      const rem = remaining.get(dep) - 1
      remaining.set(dep, rem)
      if (rem === 0) readySet.add(dep)
    }
  }

  function pickBest() {
    let best = null
    for (const n of readySet) {
      if (best === null) continue
      const pn = priority.get(n)
      const pb = priority.get(best)
      if (pn > pb || (pn === pb && n < best)) best = n
    }
    if (best === null) best = readySet.values().next().value
    return best
  }

  while (doneCount < names.length) {
    for (;;) {
      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1 || readySet.size === 0) break

      const name = pickBest()
      readySet.delete(name)
      const cost = tasks.get(name)
      const finish = currentTime + cost
      workerFreeAt[freeWorker] = finish
      workerRuns[freeWorker].push({ name, start: currentTime, finish })
      doneCount++

      if (cost === 0) {
        applyFinish(name)
      } else {
        pendingFinishes.push({ name, finish })
      }
    }

    if (doneCount === names.length) break

    let nextTime = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > currentTime) nextTime = Math.min(nextTime, workerFreeAt[i])
    }
    currentTime = nextTime

    for (let i = pendingFinishes.length - 1; i >= 0; i--) {
      if (pendingFinishes[i].finish === currentTime) {
        applyFinish(pendingFinishes[i].name)
        pendingFinishes.splice(i, 1)
      }
    }
  }

  let makespan = 0
  for (const run of workerRuns) {
    for (const t of run) makespan = Math.max(makespan, t.finish)
  }

  return { workerRuns, makespan }
}
"}

