{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-p60sZf/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 *
 * Unrecognized characters become UNKNOWN tokens rather than raising an
 * error here: the parser rejects them, which is what turns the whole
 * formula into `#ERR!`.
 */

const MULTI_OPS = ['<=', '>=', '<>']
const SINGLE_OPS = '^*/+-=<>(),:'

export function tokenize(text) {
  const tokens = []
  let i = 0
  while (i < text.length) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < text.length && text[j] >= '0' && text[j] <= '9') j++
      if (text[j] === '.' && text[j + 1] >= '0' && text[j + 1] <= '9') {
        j++
        while (j < text.length && text[j] >= '0' && text[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', value: Number(text.slice(i, j)) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < text.length && /[A-Za-z0-9]/.test(text[j])) j++
      tokens.push({ type: 'WORD', value: text.slice(i, j) })
      i = j
      continue
    }
    const two = text.slice(i, i + 2)
    if (MULTI_OPS.includes(two)) {
      tokens.push({ type: two })
      i += 2
      continue
    }
    if (SINGLE_OPS.includes(ch)) {
      tokens.push({ type: ch })
      i++
      continue
    }
    tokens.push({ type: 'UNKNOWN', value: ch })
    i++
  }
  tokens.push({ type: 'EOF' })
  return tokens
}
"}

