 * Recursive-descent parser for formula bodies, built on the token stream
 * from lexer.js.
 *
 * Precedence, loosest to tightest: comparisons, then `+`/`-`, then `*`/`/`,
 * then `^`, then a leading unary `+`/`-`. Comparisons and the additive and
 * multiplicative operators group to the left; `^` groups to the right, and
 * binds looser than a leading sign (so `-2^2` parses as `(-2)^2`).
 *
 * A range (`A1:B3`) is a general atom, accepted wherever any other atom is
 * (parenthesized, as an operand, as the whole formula, or as a function
 * argument); it is only *valid* directly as a function argument, which is
 * an evaluation-time distinction handled in evaluate.js, not a parsing one.
 * The `paren` node exists so evaluation can tell a bare range apart from
 * one wrapped in parentheses, which is no longer "direct".
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class ParseFail extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  at(type) {
    return this.peek().type === type
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    if (!this.at(type)) throw new ParseFail()
    return this.next()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (COMPARISON_OPS.has(this.peek().type)) {
      const op = this.next().type
      const right = this.parseAdditive()
      left = { k: 'bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.at('+') || this.at('-')) {
      const op = this.next().type
      const right = this.parseMultiplicative()
      left = { k: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.at('*') || this.at('/')) {
      const op = this.next().type
      const right = this.parsePower()
      left = { k: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.at('^')) {
      this.next()
      const right = this.parsePower()
      return { k: 'bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.at('-') || this.at('+')) {
      const op = this.next().type
      const expr = this.parseUnary()
      return { k: 'unary', op, expr }
    }
    return this.parseAtom()
  }

  parseAtom() {
    if (this.at('NUMBER')) return { k: 'num', v: this.next().value }
    if (this.at('(')) {
      this.next()
      const expr = this.parseComparison()
      this.expect(')')
      return { k: 'paren', expr }
    }
    if (this.at('WORD')) {
      const word = this.next().value
      const upper = word.toUpperCase()
      if (this.at('(')) {
        this.next()
        const args = this.parseArgs()
        this.expect(')')
        return { k: 'call', name: upper, args }
      }
      if (this.at(':') && this.tokens[this.pos + 1].type === 'WORD') {
        this.next()
        const to = this.next().value
        return { k: 'range', from: word, to }
      }
      if (upper === 'TRUE') return { k: 'bool', v: true }
      if (upper === 'FALSE') return { k: 'bool', v: false }
      return { k: 'addr', word }
    }
    throw new ParseFail()
  }

  parseArgs() {
    const args = []
    if (this.at(')')) return args
    args.push(this.parseComparison())
    while (this.at(',')) {
      this.next()
      args.push(this.parseComparison())
    }
    return args
  }
}

/**
 * Parses a formula body (without the leading `=`) and returns its AST, or
 * null when the grammar does not accept it.
 */
export function parseFormula(text) {
  const tokens = tokenize(text)
  const parser = new Parser(tokens)
  try {
    const ast = parser.parseComparison()
    if (!parser.at('EOF')) return null
    return ast
  } catch (e) {
    if (e instanceof ParseFail) return null
    throw e
  }
}
"}

