{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-p60sZf/src/deps.js","content":"/**
 * Static traversal of a formula's AST to find every cell it names, ranges
 * expanded. This is independent of evaluation: it runs even down branches
 * of `IF` that would never actually be evaluated, and even through a range
 * that is not directly a function argument (and so evaluates to `#ERR!`),
 * because `deps` describes what the formula names, not what it uses.
 */

import { readAddressWord, compareAddr, expandRange } from './address.js'

export function collectDeps(node) {
  const found = new Map()

  function addOne(word) {
    const addr = readAddressWord(word)
    if (addr && addr.inRange) found.set(addr.label, addr)
  }

  function addRange(fromWord, toWord) {
    const from = readAddressWord(fromWord)
    const to = readAddressWord(toWord)
    if (!from || !from.inRange || !to || !to.inRange) return
    for (const cell of expandRange(from, to)) found.set(cell.label, cell)
  }

  function walk(n) {
    switch (n.k) {
      case 'num':
      case 'bool':
        return
      case 'addr':
        addOne(n.word)
        return
      case 'range':
        addRange(n.from, n.to)
        return
      case 'paren':
      case 'unary':
        walk(n.expr)
        return
      case 'bin':
        walk(n.left)
        walk(n.right)
        return
      case 'call':
        for (const arg of n.args) walk(arg)
        return
    }
  }

  walk(node)
  return [...found.values()].sort(compareAddr).map((a) => a.label)
}
"}

