 * Recursive-descent parser for a formula body (text after the leading `=`).
 *
 * Precedence, loosest first: comparisons, +/-, * /, ^, unary sign.
 * Comparisons and +-*/ group left; ^ groups right; a leading sign binds
 * tighter than ^ (so it wraps only the atom immediately to its right).
 *
 * A range (`A1:B3`) is grammatically an atom, so it can appear anywhere an
 * atom can - operators, parens, function arguments. Whether it is *valid*
 * there (only directly as a function argument) is a semantic question,
 * decided during evaluation, not during parsing.
 */

import { tokenize } from './tokenizer.js'
import { analyzeAddressWord } from './address.js'

class ParseError extends Error {}

const COMPARISON_TYPES = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

class Cursor {
  constructor(tokens) { this.tokens = tokens; this.pos = 0 }
  peek() { return this.tokens[this.pos] }
  next() { return this.tokens[this.pos++] }
}

function expect(c, type) {
  if (c.peek().type !== type) throw new ParseError()
  return c.next()
}

function parseExpr(c) { return parseComparison(c) }

function parseComparison(c) {
  let left = parseAdditive(c)
  while (COMPARISON_TYPES.has(c.peek().type)) {
    const op = c.next().type
    const right = parseAdditive(c)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parseAdditive(c) {
  let left = parseMultiplicative(c)
  while (c.peek().type === 'PLUS' || c.peek().type === 'MINUS') {
    const op = c.next().type
    const right = parseMultiplicative(c)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parseMultiplicative(c) {
  let left = parsePower(c)
  while (c.peek().type === 'STAR' || c.peek().type === 'SLASH') {
    const op = c.next().type
    const right = parsePower(c)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parsePower(c) {
  const left = parseSignedAtom(c)
  if (c.peek().type === 'CARET') {
    c.next()
    const right = parsePower(c)
    return { type: 'binop', op: 'CARET', left, right }
  }
  return left
}

function parseSignedAtom(c) {
  if (c.peek().type === 'PLUS' || c.peek().type === 'MINUS') {
    const op = c.next().type
    const arg = parseSignedAtom(c)
    return { type: 'unary', op, arg }
  }
  return parseAtom(c)
}

function parseAtom(c) {
  const t = c.peek()
  if (t.type === 'NUM') { c.next(); return { type: 'num', value: t.value } }
  if (t.type === 'LPAREN') {
    c.next()
    const e = parseExpr(c)
    expect(c, 'RPAREN')
    return e
  }
  if (t.type === 'NAME') return parseWordAtom(c)
  throw new ParseError()
}

function parseWordAtom(c) {
  const t = c.next()
  if (c.peek().type === 'LPAREN') {
    c.next()
    const name = (t.letters + t.digits).toUpperCase()
    const args = []
    if (c.peek().type !== 'RPAREN') {
      args.push(parseExpr(c))
      while (c.peek().type === 'COMMA') { c.next(); args.push(parseExpr(c)) }
    }
    expect(c, 'RPAREN')
    return { type: 'call', name, args }
  }
  const upper = t.letters.toUpperCase()
  if (t.digits === '') {
    if (upper === 'TRUE') return { type: 'bool', value: true }
    if (upper === 'FALSE') return { type: 'bool', value: false }
  }
  if (c.peek().type === 'COLON') {
    c.next()
    const t2 = c.peek()
    if (t2.type !== 'NAME') throw new ParseError()
    c.next()
    const from = analyzeAddressWord(t.letters, t.digits)
    const to = analyzeAddressWord(t2.letters, t2.digits)
    return { type: 'range', from, to }
  }
  return { type: 'addr', info: analyzeAddressWord(t.letters, t.digits) }
}

/** Returns the AST for a formula body, or null when the grammar rejects it. */
export function parseFormula(text) {
  const tok = tokenize(text)
  if (!tok.ok) return null
  const c = new Cursor(tok.tokens)
  try {
    const ast = parseExpr(c)
    if (c.peek().type !== 'EOF') return null
    return ast
  } catch (e) {
    if (e instanceof ParseError) return null
    throw e
  }
}
"}

