import { NUM, BOOL, ERR, toNumber, numResult, divide, compareValues } from './value.js'
import { rangeValid, expandRange } from './range.js'
import { FUNCTIONS } from './functions.js'

function evalUnary(op, val) {
  if (val.t === 'err') return val
  const n = toNumber(val)
  if (n.t === 'err') return n
  return NUM(op === 'MINUS' ? -n.v : n.v)
}

const COMPARISON_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

function evalComparison(op, left, right) {
  const cmp = compareValues(left, right)
  switch (op) {
    case 'EQ': return BOOL(cmp === 0)
    case 'NE': return BOOL(cmp !== 0)
    case 'LT': return BOOL(cmp < 0)
    case 'LE': return BOOL(cmp <= 0)
    case 'GT': return BOOL(cmp > 0)
    case 'GE': return BOOL(cmp >= 0)
  }
}

function evalArithmetic(op, left, right) {
  const ln = toNumber(left)
  if (ln.t === 'err') return ln
  const rn = toNumber(right)
  if (rn.t === 'err') return rn
  switch (op) {
    case 'PLUS': return numResult(ln.v + rn.v)
    case 'MINUS': return numResult(ln.v - rn.v)
    case 'STAR': return numResult(ln.v * rn.v)
    case 'SLASH': return divide(ln.v, rn.v)
    case 'CARET': return numResult(Math.pow(ln.v, rn.v))
  }
}

function evalBinop(op, left, right) {
  if (left.t === 'err') return left
  if (right.t === 'err') return right
  if (COMPARISON_OPS.has(op)) return evalComparison(op, left, right)
  return evalArithmetic(op, left, right)
}

/** Evaluates a scalar AST node. A bare `range` node is invalid here (#ERR!). */
export function evalAst(node, getValue) {
  switch (node.type) {
    case 'num': return NUM(node.value)
    case 'bool': return BOOL(node.value)
    case 'addr': return node.info.inRange ? getValue(node.info.canonical) : ERR('#REF!')
    case 'range': return ERR('#ERR!')
    case 'unary': return evalUnary(node.op, evalAst(node.arg, getValue))
    case 'binop': return evalBinop(node.op, evalAst(node.left, getValue), evalAst(node.right, getValue))
    case 'call': return evalCall(node, getValue)
  }
