/** Expands a single argument node into its list of contributed values. */
export function expandArgToValues(node, getValue) {
  if (node.type === 'range') {
    if (!rangeValid(node)) return [ERR('#REF!')]
    return expandRange(node).map(getValue)
  }
  return [evalAst(node, getValue)]
}

