  const fn = FUNCTIONS[node.name]
  if (!fn) return ERR('#NAME?')
  return fn(node.args, getValue)
}

/** Builds a getValue(address) function with memoized, cycle-detecting cell evaluation. */
export function createCellReader(cells, parseFormula) {
  const state = new Map() // address -> 'visiting' | 'done'
  const cache = new Map()

  function evalContent(content) {
    if (content === '') return NUM(0)
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (!ast) return ERR('#ERR!')
      return evalAst(ast, getValue)
    }
    return require_literal(content)
  }

  function getValue(address) {
    if (cache.has(address)) return cache.get(address)
    if (state.get(address) === 'visiting') return ERR('#CYCLE!')
    state.set(address, 'visiting')
    const content = cells.has(address) ? cells.get(address) : ''
    const val = evalContent(content)
    state.set(address, 'done')
    cache.set(address, val)
    return val
  }

  return getValue
