{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-rkhytK/src/functions.js","content":"/**
 * Formula function implementations: SUM, MIN, MAX, COUNT, AVG, ABS, IF.
 *
 * Each argument node contributes one or more values (a range expands to
 * every cell it covers); the flattened, left-to-right list is what the
 * aggregate functions work over. ABS and IF each want exactly one value
 * per argument slot, so a slot whose expansion isn't exactly one value is
 * `#ERR!`.
 */

import { NUM, ERR, toNumber, numResult } from './value.js'
import { evalAst, expandArgToValues } from './evaluate.js'

function flattenArgs(args, getValue) {
  const values = []
  for (const arg of args) values.push(...expandArgToValues(arg, getValue))
  return values
}

/** Reads values as numbers left to right, short-circuiting on the first error. */
function readNumbers(values) {
  const numbers = []
  for (const v of values) {
    if (v.t === 'err') return { error: v }
    const n = toNumber(v)
    if (n.t === 'err') return { error: n }
    numbers.push(n.v)
  }
  return { numbers }
}

function aggregate(compute) {
  return (args, getValue) => {
    if (args.length < 1) return ERR('#ERR!')
    const { error, numbers } = readNumbers(flattenArgs(args, getValue))
    if (error) return error
    return compute(numbers)
  }
}

function scalarArg(node, getValue) {
  const values = expandArgToValues(node, getValue)
  if (values.length !== 1) return ERR('#ERR!')
  return values[0]
}

export const FUNCTIONS = {
  SUM: aggregate((numbers) => numResult(numbers.reduce((a, b) => a + b, 0))),
  MIN: aggregate((numbers) => NUM(Math.min(...numbers))),
  MAX: aggregate((numbers) => NUM(Math.max(...numbers))),
  AVG: aggregate((numbers) => numResult(numbers.reduce((a, b) => a + b, 0) / numbers.length)),

  COUNT(args, getValue) {
    if (args.length < 1) return ERR('#ERR!')
    const values = flattenArgs(args, getValue)
    for (const v of values) if (v.t === 'err') return v
    return NUM(values.filter((v) => v.t === 'num').length)
  },

  ABS(args, getValue) {
    if (args.length !== 1) return ERR('#ERR!')
    const v = scalarArg(args[0], getValue)
    if (v.t === 'err') return v
    const n = toNumber(v)
    if (n.t === 'err') return n
    return NUM(Math.abs(n.v))
  },

  IF(args, getValue) {
    if (args.length !== 3) return ERR('#ERR!')
    const condVal = scalarArg(args[0], getValue)
    if (condVal.t === 'err') return condVal
    const condNum = toNumber(condVal)
    if (condNum.t === 'err') return condNum
    const branch = condNum.v !== 0 ? args[1] : args[2]
    return scalarArg(branch, getValue)
  },
}
"}

