import { rangeValid, expandRange } from './range.js'
import { colLettersToIndex } from './address.js'

function walk(node, out) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'addr':
      if (node.info.inRange) out.add(node.info.canonical)
      return
    case 'range':
      if (rangeValid(node)) for (const a of expandRange(node)) out.add(a)
      return
    case 'unary':
      walk(node.arg, out)
      return
    case 'binop':
      walk(node.left, out)
      walk(node.right, out)
      return
    case 'call':
      for (const arg of node.args) walk(arg, out)
      return
  }
}

function addressSortKey(address) {
  const m = /^([A-Z]{1,2})([0-9]+)$/.exec(address)
  return { colIndex: colLettersToIndex(m[1]), row: parseInt(m[2], 10) }
}

/** Returns the distinct addresses an AST names, ordered by column then row. */
export function formulaDeps(ast) {
  const out = new Set()
  walk(ast, out)
  return [...out].sort((a, b) => {
    const ka = addressSortKey(a), kb = addressSortKey(b)
    if (ka.colIndex !== kb.colIndex) return ka.colIndex - kb.colIndex
    return ka.row - kb.row
  })
