 * Renders a parsed document as either indented JSON or a flat listing of
 * every node's path and type.
 */
import { orderedKeys } from './document.js'

function typeName(node) {
  if (node.t === 'array-of-tables') return 'array'
  return node.t
}

function jsonString(v) {
  return JSON.stringify(v)
}

function toJSON(node, indent) {
  const pad = '  '.repeat(indent)
  const pad1 = '  '.repeat(indent + 1)
  switch (node.t) {
    case 'table': {
      const keys = orderedKeys(node)
      if (keys.length === 0) return '{}'
      const lines = keys.map((k) => `${pad1}${jsonString(k)}: ${toJSON(node.map.get(k), indent + 1)}`)
      return `{\n${lines.join(',\n')}\n${pad}}`
    }
    case 'array-of-tables':
    case 'array': {
      const items = node.t === 'array' ? node.items : node.arr
      if (items.length === 0) return '[]'
      const lines = items.map((it) => `${pad1}${toJSON(it, indent + 1)}`)
      return `[\n${lines.join(',\n')}\n${pad}]`
    }
    case 'string':
      return jsonString(node.v)
    case 'boolean':
      return node.v ? 'true' : 'false'
    case 'integer':
      return node.v.toString()
    case 'float':
      return jsonString(node.v)
    default:
      throw new Error(`unknown node type ${node.t}`)
  }
}

export function renderJSON(root) {
  return `${toJSON(root, 0)}\n`
}

function collectKeysLines(node, path, out) {
  if (node.t === 'table') {
    for (const k of orderedKeys(node)) {
      const child = node.map.get(k)
      const childPath = path === '' ? k : `${path}.${k}`
      out.push(`${childPath} ${typeName(child)}`)
      collectKeysLines(child, childPath, out)
    }
  } else if (node.t === 'array' || node.t === 'array-of-tables') {
    const items = node.t === 'array' ? node.items : node.arr
    items.forEach((it, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeName(it)}`)
      collectKeysLines(it, childPath, out)
    })
  }
}

export function renderKeys(root) {
  const out = []
  collectKeysLines(root, '', out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
