  if (ch === '{') return parseInlineTableValue(line, pos, lineNo, pathPrefix)

  const token = /^[^\s,\]}]+/.exec(line.slice(pos))[0]
  const nextPos = pos + token.length
  if (token === 'true') return { node: makeBoolean(true), pos: nextPos }
  if (token === 'false') return { node: makeBoolean(false), pos: nextPos }
  if (INTEGER_RE.test(token)) return { node: makeInteger(normalizeInteger(token)), pos: nextPos }
  if (FLOAT_RE.test(token)) return { node: makeFloat(Number(token.replace(/_/g, ''))), pos: nextPos }
