  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  let currentTable = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const lineNo = i + 1
    if (isBlankLine(line)) continue

    const pos0 = skipWs(line, 0)
    if (line[pos0] === '[') {
      const header = parseHeader(root, line, pos0, lineNo)
      currentTable = header.currentTable
      currentPath = header.currentPath
    } else {
      applyAssignment(currentTable, currentPath, line, pos0, lineNo)
    }
  }

  return root
}

function parseHeader(root, line, pos0, lineNo) {
  let pos = pos0
  const isArray = line[pos] === '[' && line[pos + 1] === '['
  pos += isArray ? 2 : 1
  pos = skipWs(line, pos)

  const name = parseDottedName(line, pos, lineNo)
  const parts = name.parts
  pos = skipWs(line, name.pos)

  if (isArray) {
    if (line[pos] !== ']' || line[pos + 1] !== ']') throw new ParseError(lineNo, 'unterminated table header')
    pos += 2
  } else {
    if (line[pos] !== ']') throw new ParseError(lineNo, 'unterminated table header')
    pos += 1
  }

  pos = skipWs(line, pos)
  if (pos < line.length && line[pos] !== '#' && line[pos] !== ';') {
    throw new ParseError(lineNo, 'trailing text after a table header')
  }

  const parent = walkIntermediate(root, parts, [], lineNo)
  const lastKey = parts[parts.length - 1]
  const fullPath = parts.join('.')
  const existing = parent.map.get(lastKey)

  if (isArray) {
    let arr = existing
    if (arr === undefined) {
      arr = makeArrayOfTables()
      parent.map.set(lastKey, arr)
    } else if (arr.kind !== 'arrayOfTables') {
      throw new ParseError(lineNo, `${fullPath} is not an array of tables`)
    }
    const table = makeTable()
    arr.items.push(table)
    return { currentTable: table, currentPath: parts }
  }

  let table = existing
  if (table === undefined) {
    table = makeTable()
    table.headerUsed = true
    parent.map.set(lastKey, table)
  } else if (table.kind === 'table') {
    if (table.headerUsed) throw new ParseError(lineNo, `table ${fullPath} is defined twice`)
    table.headerUsed = true
  } else {
    throw new ParseError(lineNo, `${fullPath} is not a table`)
  }
  return { currentTable: table, currentPath: parts }
