{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-xhIvf8/src/policies.js","content":"/**
 * The two policy kinds a route can enforce. Both keep one independent state
 * per key, and both expose the same three-step protocol the simulator
 * drives: `advance` to a tick, `allow` to ask, `record` to spend.
 */

/**
 * A token bucket. Tokens are tracked as `tokens * per` in a BigInt so that
 * the fractional refill per tick (`refill / per` tokens each tick) is never
 * rounded away.
 */
export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityNum = capacity * per
    this.state = new Map()
  }

  advance(tick, key) {
    const existing = this.state.get(key)
    if (!existing) {
      this.state.set(key, { tokensNum: this.capacityNum, lastTick: tick })
      return
    }
    const elapsed = tick - existing.lastTick
    if (elapsed > 0n) {
      const grown = existing.tokensNum + this.refill * elapsed
      existing.tokensNum = grown > this.capacityNum ? this.capacityNum : grown
    }
    existing.lastTick = tick
  }

  allow(key) {
    return this.state.get(key).tokensNum >= this.per
  }

  record(key) {
    const state = this.state.get(key)
    state.tokensNum -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it recorded for a
 * key, in a queue that stays in non-decreasing order because ticks never go
 * backwards across the whole file.
 */
export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.state = new Map()
  }

  advance(tick, key) {
    let queue = this.state.get(key)
    if (!queue) {
      queue = []
      this.state.set(key, queue)
    }
    const threshold = tick - this.span
    let drop = 0
    while (drop < queue.length && queue[drop] <= threshold) drop++
    if (drop > 0) queue.splice(0, drop)
  }

  allow(key) {
    return BigInt(this.state.get(key).length) < this.limit
  }

  record(key, tick) {
    this.state.get(key).push(tick)
  }
}
"}

