{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-xhIvf8/src/router.js","content":"/**
 * Picks the route that governs a key: the longest declared prefix the key
 * starts with. No two declared prefixes can both be the longest match for
 * the same key unless they are identical, and prefixes are unique, so the
 * match is unambiguous.
 */
export function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (!key.startsWith(route.prefix)) continue
    if (best === null || route.prefix.length > best.prefix.length) best = route
  }
  return best
}
"}

